255	/// Initialize a watch session with a full cold extraction.
256	/// Returns JSON string of ExtractionOutput.
257	/// Call this after create_session(), in configureServer.
258	#[napi]
259	pub async fn initialize_session(session_id: u32, options: JsExtractOptions) -> napi::Result<String> {
260	    tokio::task::spawn_blocking(move || {
261	        match oxc_react_docgen_core::panic_guard::contain_panic("initialize_session", move || {
262	            let session = match SESSIONS.get(&session_id) {
263	                Some(s) => s.clone(),
264	                None => {
265	                    #[cfg(test)]
266	                    if session_id == AUTO_VIVIFY_PANIC_TEST_SENTINEL {
267	                        panic!("simulated initialize_session auto-vivification panic (test-only sentinel)");
268	                    }
269	
270	                    let pipeline_options = PipelineOptions::try_from(options).map_err(napi::Error::from_reason)?;
271	                    let s = Arc::new(WatchSession::new(pipeline_options));
272	                    SESSIONS.insert(session_id, s.clone());
273	                    s
274	                }
275	            };
276	
277	            #[cfg(test)]
278	            if session_id == INITIALIZE_SESSION_PANIC_TEST_SENTINEL {
279	                panic!("simulated initialize_session core-call panic (test-only sentinel)");
280	            }
281	
282	            let output = session.initialize();
283	            oxc_react_docgen_core::pipeline::extraction_output_to_json(&output)
284	                .map_err(|e| napi::Error::from_reason(e.to_string()))
285	        }) {
286	            Ok(result) => result,
287	            Err(diag) => Err(napi::Error::from_reason(diag.to_string())),
288	        }
289	    })
290	    .await
291	    .map_err(|e| napi::Error::from_reason(e.to_string()))?
292	}
