471	    // ── SPEC-BINDING-001 AC9: an unrecognized session_id auto-vivifies
472	    // instead of failing; a second call with the same ID reuses the entry
473	    // rather than constructing another.
474	
475	    #[tokio::test]
476	    async fn initialize_session_auto_vivifies_on_first_call_and_reuses_on_second() {
477	        let session_id = next_session_id();
478	        assert!(SESSIONS.get(&session_id).is_none(), "sanity check: session must not already exist");
479	
480	        let first = initialize_session(session_id, base_options()).await;
481	        assert!(first.is_ok(), "expected Ok for an unrecognized session_id, got {first:?}");
482	        assert!(SESSIONS.get(&session_id).is_some(), "expected the session to now be registered");
483	
484	        // Reuse: a second call with the same ID must not error, and SESSIONS
485	        // must still have exactly one entry for it (not silently replaced —
486	        // DashMap::insert on the same key would look identical either way,
487	        // so the real proof is simply that this call succeeds against the
488	        // now-initialized session rather than re-erroring on construction).
489	        let second = initialize_session(session_id, base_options()).await;
490	        assert!(second.is_ok(), "expected Ok on reuse, got {second:?}");
491	    }
