9	/// Cap on a single LSP frame's declared `Content-Length`, checked *before*
10	/// `vec![0u8; len]` allocates — `Content-Length` is client-controlled input
11	/// with no upper bound of its own.
12	const MAX_LSP_MESSAGE_BYTES: usize = 16 * 1024 * 1024; // 16 MiB
13	
14	/// Reject an oversized frame before its receive buffer is allocated.
15	fn check_content_length(len: usize) -> Result<()> {
16	    if len > MAX_LSP_MESSAGE_BYTES {
17	        tracing::error!(
18	            "LSP frame declared Content-Length {len} bytes, exceeding the {MAX_LSP_MESSAGE_BYTES}-byte cap; closing connection"
19	        );
20	        return Err(miette::miette!(
21	            "LSP frame declared Content-Length {len} bytes, exceeding the {MAX_LSP_MESSAGE_BYTES}-byte cap"
22	        ));
23	    }
24	    Ok(())
25	}
26	
27	/// Reads header lines up to the blank-line terminator and returns the parsed
28	/// `Content-Length`, if any.
29	///
30	/// `Err(())` means the stream ended before any header line was read at all —
31	/// a normal, expected way for a client to close the connection.
32	/// `Ok(None)` means a header block *was* read (the loop reached the blank
33	/// line) but it contained no usable `Content-Length` — missing header or an
34	/// unparsable value. That body's byte length is unknowable, so the caller
35	/// must not keep reading from the stream as if nothing happened: doing so
36	/// desyncs every subsequent frame, since the unconsumed body bytes get read
37	/// as the start of the *next* header block.
38	fn read_content_length<R: BufRead>(reader: &mut R) -> Result<Option<usize>, ()> {
39	    let mut content_length: Option<usize> = None;
40	    let mut line = String::new();
41	
42	    loop {
43	        line.clear();
44	        if reader.read_line(&mut line).unwrap_or(0) == 0 {
45	            return Err(());
46	        }
47	        if line == "\r\n" || line == "\n" {
48	            break;
49	        }
50	        if let Some(header) = line.strip_prefix("Content-Length: ") {
51	            content_length = header.trim().parse().ok();
52	        }
53	    }
54	
55	    Ok(content_length)
56	}
