141	/// Reverse dependency graph: file → list of files that import from it.
142	/// Built once from GlobalSourceData; used by WatchSession for BFS propagation.
143	pub struct ReverseDeps {
144	    pub(super) inner: FxHashMap<Utf8PathBuf, Vec<Utf8PathBuf>>,
145	}
146	
147	impl ReverseDeps {
148	    /// Build from a fully-merged GlobalSourceData.
149	    pub fn build(global: &GlobalSourceData) -> Self {
150	        let mut inner: FxHashMap<Utf8PathBuf, Vec<Utf8PathBuf>> = Default::default();
151	
152	        for (consumer_file, imports) in &global.import_map {
153	            for import in imports {
154	                // Only chase relative imports — package imports can't be naively reversed.
155	                if import.specifier.starts_with('.') {
156	                    if let Some(parent) = consumer_file.parent() {
157	                        let target = parent.join(&import.specifier);
158	                        // Approximate extension normalization without I/O.
159	                        for ext in &[".ts", ".tsx", "/index.ts", "/index.tsx"] {
160	                            let candidate = Utf8PathBuf::from(format!("{}{}", target, ext));
161	                            inner.entry(candidate).or_default().push(consumer_file.clone());
162	                        }
163	                    }
164	                }
165	            }
166	        }
167	
168	        Self { inner }
169	    }
170	
171	    /// BFS: collect all files transitively affected by a change to `changed`.
172	    pub fn affected(&self, changed: &Utf8Path) -> FxHashSet<Utf8PathBuf> {
173	        let mut visited: FxHashSet<Utf8PathBuf> = Default::default();
174	        let mut queue: VecDeque<Utf8PathBuf> = VecDeque::new();
175	        queue.push_back(changed.to_owned());
176	
177	        while let Some(file) = queue.pop_front() {
178	            if visited.insert(file.clone()) {
179	                for dep in self.inner.get(&file).into_iter().flatten() {
180	                    queue.push_back(dep.clone());
181	                }
182	            }
183	        }
184	
185	        visited
186	    }
187	}
