15	) -> (Vec<Utf8PathBuf>, Vec<Diagnostic>) {
16	    let mut files = Vec::new();
17	    let mut diagnostics = Vec::new();
18	
19	    for dir in src_dirs {
20	        // If the user explicitly points at a node_modules path, respect it.
21	        let dir_str = dir.as_str();
22	        let dir_is_in_node_modules = dir_str.contains("node_modules");
23	
24	        let walker =
25	            ignore::WalkBuilder::new(dir.as_std_path()).hidden(false).git_ignore(!dir_is_in_node_modules).build();
26	
27	        for result in walker {
28	            let entry = match result {
29	                Ok(entry) => entry,
30	                Err(err) => {
31	                    diagnostics.push(Diagnostic {
32	                        severity: DiagnosticSeverity::Warning,
33	                        message: format!("Error walking '{dir}': {err}"),
34	                        file: Some(dir.to_string()),
35	                        line: None,
36	                        column: None,
37	                        help: Some("Check file/directory permissions and for broken symlinks under this path.".into()),
38	                        code: DiagnosticCode::IoError,
39	                    });
40	                    continue;
41	                }
42	            };
43	            let path = entry.path();
44	            let ext = path.extension().and_then(|e| e.to_str()).unwrap_or("");
45	            if !matches!(ext, "ts" | "tsx") {
46	                continue;
47	            }
48	
49	            let path_str = path.to_str().unwrap_or("");
50	
51	            // Built-in excludes — skip node_modules sub-dirs only when not intentionally targeting them.
52	            if path_str.contains(".stories.")
53	                || path_str.contains(".test.")
54	                || path_str.contains(".spec.")
55	                || path_str.contains("__snapshots__")
56	                || (!dir_is_in_node_modules && path_str.contains("node_modules"))
57	            {
58	                continue;
59	            }
60	
61	            // User-supplied excludes.
62	            if extra_excludes.iter().any(|p| path_str.contains(p.as_str())) {
63	                continue;
64	            }
65	
66	            if let Ok(utf8) = Utf8PathBuf::from_path_buf(path.to_owned()) {
67	                // Canonicalize to an absolute path so parent.fileName in output is
68	                // stable regardless of invocation context (relative --src, absolute
69	                // --src, or cwd inside the src dir all previously produced different
70	                // strings for the same file). Fall back to the uncanonicalized path
71	                // if canonicalization fails (e.g. a dangling symlink) rather than
72	                // dropping the file.
73	                let canonical = utf8.canonicalize_utf8().unwrap_or(utf8);
74	                files.push(canonical);
75	            } else {
76	                diagnostics.push(Diagnostic {
77	                    severity: DiagnosticSeverity::Warning,
78	                    message: format!("Skipping non-UTF8 path: {}", path.to_string_lossy()),
79	                    file: None,
80	                    line: None,
81	                    column: None,
82	                    help: Some("Rename the file to use valid UTF-8 characters in its path.".into()),
83	                    code: DiagnosticCode::IoError,
84	                });
85	            }
86	        }
87	    }
88	
89	    // Sort for deterministic ordering across OS/FS, then dedup: overlapping
90	    // src_dirs (e.g. ["./src", "./src/components"]) walk the same physical
91	    // file more than once, and since paths are canonicalized above, an exact
92	    // duplicate always sorts adjacent — this catches it here rather than
93	    // producing two separate component_mappings downstream.
94	    files.sort();
95	    files.dedup();
96	    (files, diagnostics)
97	}
