16	fn unwrap_as_expression<'a, 'b>(expr: &'b Expression<'a>) -> &'b Expression<'a> {
17	    let mut expr = expr;
18	    while let Expression::TSAsExpression(as_expr) = expr {
19	        expr = &as_expr.expression;
20	    }
21	    expr
22	}
