97	                })
98	            }
99	            TSType::TSParenthesizedType(p) => {
100	                self.extract_props_from_type_annotation(&p.type_annotation, name, span_start, span_end, init_params)
101	            }
102	            _ => None,
103	        }
104	    }
105	
106	    /// Try to detect: `const Button = React.forwardRef<HTMLButtonElement, ButtonProps>(...)`
107	    pub(super) fn try_forward_ref<'a>(
108	        &mut self,
109	        decl: &VariableDeclarator<'a>,
110	        name: &str,
111	    ) -> Option<ComponentMapping> {
112	        let init = decl.init.as_ref()?;
113	        let call = match unwrap_as_expression(init) {
114	            Expression::CallExpression(ce) => ce,
115	            _ => return None,
116	        };
117	        let callee_name = self.extract_callee_name(call)?;
118	
119	        if !matches!(callee_name.as_str(), "forwardRef" | "React.forwardRef") {
120	            return None;
121	        }
122	
123	        // forwardRef<RefType, PropsType>(fn) — PropsType is the second type parameter
124	        let type_params = call.type_arguments.as_ref()?;
125	        if type_params.params.len() < 2 {
126	            return None;
127	        }
128	        let props_type = &type_params.params[1];
129	        let (props_name, type_args) = self.extract_type_name_from_type(props_type)?;
130	
131	        // The render function is forwardRef's call argument — its first parameter is
132	        // props (the second is `ref`, which never carries destructured defaults we care about).
133	        let render_params = match call.arguments.first() {
134	            Some(Argument::FunctionExpression(fe)) => Some(&fe.params),
135	            Some(Argument::ArrowFunctionExpression(afe)) => Some(&afe.params),
136	            _ => None,
137	        };
138	        let param_defaults = render_params.map(|p| self.extract_param_defaults(p)).unwrap_or_default();
139	        let (description, tags) = self.find_jsdoc_with_tags(decl.span.start);
140	
141	        Some(ComponentMapping {
142	            component_name: name.to_owned(),
143	            props_type_name: props_name,
144	            props_type_args: type_args,
145	            file_path: self.file_path.clone(),
146	            description,
147	            tags,
148	            span_start: decl.span.start,
149	            span_end: decl.span.end,
150	            param_defaults,
151	        })
152	    }
153	
154	    /// Try to detect: `const Button = anyHOC(function Button(props: ButtonProps) {...})`
155	    pub(super) fn try_hoc_wrapped<'a>(
156	        &mut self,
157	        decl: &VariableDeclarator<'a>,
158	        name: &str,
159	    ) -> Option<ComponentMapping> {
160	        let init = decl.init.as_ref()?;
161	        let call = match unwrap_as_expression(init) {
162	            Expression::CallExpression(ce) => ce,
163	            _ => return None,
164	        };
165	
166	        // First arg should be a function with a typed props param — or a forwardRef() call.
167	        let first_arg = call.arguments.first()?;
168	
169	        // Handle memo(forwardRef<Ref, Props>(...)) — inner call is forwardRef
170	        if let Argument::CallExpression(inner) = first_arg {
171	            if let Some(inner_name) = self.extract_callee_name(inner) {
172	                if matches!(inner_name.as_str(), "forwardRef" | "React.forwardRef") {
173	                    let type_params = inner.type_arguments.as_ref()?;
174	                    if type_params.params.len() >= 2 {
175	                        let (props_name, type_args) = self.extract_type_name_from_type(&type_params.params[1])?;
176	                        let (description, tags) = self.find_jsdoc_with_tags(decl.span.start);
177	                        return Some(ComponentMapping {
178	                            component_name: name.to_owned(),
179	                            props_type_name: props_name,
180	                            props_type_args: type_args,
181	                            file_path: self.file_path.clone(),
182	                            description,
183	                            tags,
184	                            span_start: decl.span.start,
185	                            span_end: decl.span.end,
186	                            param_defaults: Default::default(),
187	                        });
188	                    }
189	                }
190	            }
191	            return None;
192	        }
193	
194	        let (fn_name, params) = match first_arg {
195	            Argument::FunctionExpression(fe) => (fe.id.as_ref().map(|id| id.name.as_str()), &fe.params),
196	            Argument::ArrowFunctionExpression(afe) => (None, &afe.params),
197	            _ => return None,
198	        };
199	
200	        // Rules out anonymous utility functions, which aren't components.
201	        if let Some(fn_name_str) = fn_name {
202	            if !is_pascal_case(fn_name_str) {
203	                return None;
204	            }
205	        }
206	
207	        let first_param = params.items.first()?;
208	        let type_ann = first_param.type_annotation.as_ref()?;
209	        let (props_name, type_args) = self.extract_type_name_from_type(&type_ann.type_annotation)?;
210	
211	        let param_defaults = self.extract_param_defaults(params);
212	        let (description, tags) = self.find_jsdoc_with_tags(decl.span.start);
213	
214	        Some(ComponentMapping {
215	            component_name: name.to_owned(),
216	            props_type_name: props_name,
217	            props_type_args: type_args,
218	            file_path: self.file_path.clone(),
219	            description,
220	            tags,
221	            span_start: decl.span.start,
222	            span_end: decl.span.end,
223	            param_defaults,
224	        })
225	    }
226	
227	    /// Try to detect: `declare const Button: React.ForwardRefExoticComponent<ButtonProps & RefAttributes<E>>`
228	    ///
229	    /// Common in .d.ts files — no initializer, just a type annotation.
230	    pub(super) fn try_forward_ref_exotic_decl<'a>(
231	        &mut self,
232	        decl: &VariableDeclarator<'a>,
233	        name: &str,
234	    ) -> Option<ComponentMapping> {
235	        let type_ann = decl.type_annotation.as_ref()?;
236	        let ct = self.ts_type_to_collected(&type_ann.type_annotation);
237	
238	        let (type_name, args) = match &ct {
239	            crate::types::CollectedType::Named { name, args } => (name.as_str(), args.as_slice()),
240	            _ => return None,
241	        };
242	
243	        if !matches!(type_name, "ForwardRefExoticComponent" | "React.ForwardRefExoticComponent") {
244	            return None;
245	        }
246	
247	        let first_arg = args.first()?;
248	
249	        // Extract P from P & RefAttributes<E>
250	        let props_type = match first_arg {
251	            crate::types::CollectedType::Intersection(members) => members
252	                .iter()
253	                .find(|m| {
254	                    !matches!(m, crate::types::CollectedType::Named { name, .. }
255	                            if matches!(name.as_str(), "RefAttributes" | "React.RefAttributes"))
256	                })
257	                .unwrap_or(first_arg),
258	            other => other,
259	        };
260	
261	        let (props_name, props_args) = match props_type {
262	            crate::types::CollectedType::Named { name, args } => (name.clone(), args.clone()),
263	            _ => return None,
264	        };
265	
266	        // Convert args to strings for ComponentMapping (resolver will re-parse)
267	        let props_type_args: Vec<String> = props_args.iter().map(|a| a.to_raw_string()).collect();
268	
269	        Some(ComponentMapping {
270	            component_name: name.to_owned(),
271	            props_type_name: props_name,
272	            props_type_args,
273	            file_path: self.file_path.clone(),
274	            description: self.find_jsdoc(decl.span.start),
275	            tags: BTreeMap::new(),
276	            span_start: decl.span.start,
277	            span_end: decl.span.end,
278	            param_defaults: rustc_hash::FxHashMap::default(),
279	        })
280	    }
281	
282	    /// Rename an already-collected component mapping to its real public export name
283	    /// when the mapping's own identifier is immediately wrapped by an *unrecognized*
284	    /// call and reassigned to a new binding — e.g. Headless UI's real
285	    /// `export let ListboxButton = forwardRefWithAs(ButtonFn) as X`. `forwardRefWithAs`
286	    /// is a library-defined wrapper, not `React.forwardRef` itself, so `try_forward_ref`
287	    /// never matches it; meanwhile `ButtonFn` — a standalone top-level function
288	    /// declaration — was already independently collected as its own component by the
289	    /// `visit_function` Pattern 4 check, under the wrong (inner, implementation-only)
290	    /// name. Without this, the real export name never appears at all.
291	    ///
292	    /// Also handles the same rename with no wrapper call at all — a bare passthrough
293	    /// alias, `const Button = InternalCompoundedButton;` (optionally `as X`), antd's
294	    /// real `Button` export shape.
295	    ///
296	    /// Clones the matched mapping under the new name rather than renaming it in
297	    /// place: a second, different alias to the same base
298	    /// (`const A = Base; const Bcopy = Base;`) is a genuinely distinct exported
299	    /// binding, not the same rename twice, and renaming in place would make the
300	    /// base unfindable for that second alias — silently dropping it. The base's
301	    /// own (implementation-only) name is filtered out of the final output in
302	    /// `finish()` via `aliased_away`.
303	    pub(super) fn try_rename_identifier_wrapped_component<'a>(
304	        &mut self,
305	        decl: &VariableDeclarator<'a>,
306	        name: &str,
307	    ) -> bool {
308	        let Some(init) = decl.init.as_ref() else { return false };
309	        let inner_name = match unwrap_as_expression(init) {
310	            Expression::CallExpression(call) => match call.arguments.first() {
311	                Some(Argument::Identifier(id)) => id.name.as_str(),
312	                _ => return false,
313	            },
314	            Expression::Identifier(id) => id.name.as_str(),
315	            _ => return false,
316	        };
317	
318	        let Some(base) = self.data.component_mappings.iter().find(|m| m.component_name == inner_name) else {
319	            return false;
320	        };
321	        let mut alias = base.clone();
322	        alias.component_name = name.to_owned();
323	        self.data.component_mappings.push(alias);
324	        self.aliased_away.insert(inner_name.into());
325	        true
326	    }
327	
328	    /// Extract the callee name of a call expression (simple ident or member expr).
329	    pub(super) fn extract_callee_name<'a>(&self, call: &CallExpression<'a>) -> Option<String> {
330	        match &call.callee {
331	            Expression::Identifier(id) => Some(id.name.as_str().to_owned()),
332	            Expression::StaticMemberExpression(me) => {
333	                Some(format!("{}.{}", self.expression_to_ident_name(&me.object), me.property.name.as_str()))
334	            }
335	            _ => None,
336	        }
337	    }
338	}
