1	//! `impl Visit for SourceDataCollector` — the AST walker entry points.
2	
3	use oxc_ast::ast::*;
4	use oxc_ast_visit::{walk, Visit};
5	use oxc_syntax::scope::ScopeFlags;
6	
7	use crate::types::{
8	    CollectedInterface, ComponentMapping, DiagnosticCode, EnumEntry, EnumValue, ExtendsRef, ImportBinding, LexedExport,
9	    RawProp, TypeName,
10	};
11	
12	use super::{declaration_name, is_pascal_case, SourceDataCollector};
13	
14	impl<'a, 'src> Visit<'a> for SourceDataCollector<'src> {
15	    fn visit_import_declaration(&mut self, node: &ImportDeclaration<'a>) {
16	        let specifier = node.source.value.as_str().to_owned();
17	        let is_type_only = node.import_kind.is_type();
18	
19	        if let Some(specifiers) = &node.specifiers {
20	            for spec in specifiers {
21	                match spec {
22	                    ImportDeclarationSpecifier::ImportSpecifier(s) => {
23	                        let local = s.local.name.as_str();
24	                        let imported = s.imported.name();
25	                        let imported_str = imported.as_str();
26	                        self.imported_names.insert(local.into());
27	                        self.data.imports.push(ImportBinding {
28	                            local_name: local.into(),
29	                            exported_name: imported_str.into(),
30	                            specifier: specifier.clone(),
31	                            is_type_only: is_type_only || s.import_kind.is_type(),
32	                        });
33	                    }
34	                    ImportDeclarationSpecifier::ImportDefaultSpecifier(s) => {
35	                        let local = s.local.name.as_str();
36	                        self.imported_names.insert(local.into());
37	                        self.data.imports.push(ImportBinding {
38	                            local_name: local.into(),
39	                            exported_name: "default".into(),
40	                            specifier: specifier.clone(),
41	                            is_type_only,
42	                        });
43	                    }
44	                    ImportDeclarationSpecifier::ImportNamespaceSpecifier(s) => {
45	                        let local = s.local.name.as_str();
46	                        self.imported_names.insert(local.into());
47	                        self.data.imports.push(ImportBinding {
48	                            local_name: local.into(),
49	                            exported_name: "*".into(),
50	                            specifier: specifier.clone(),
51	                            is_type_only,
52	                        });
53	                    }
54	                }
55	            }
56	        }
57	
58	        // Don't walk children — we've handled everything
59	    }
60	
61	    fn visit_export_named_declaration(&mut self, node: &ExportNamedDeclaration<'a>) {
62	        if let Some(source) = &node.source {
63	            // Re-exports: `export { X } from "./y"`
64	            let src = source.value.as_str().to_owned();
65	            for spec in &node.specifiers {
66	                self.data.exports.push(LexedExport::ReExportNamed {
67	                    // local_name is what we call it here; source_name is the original
68	                    local_name: spec.exported.name().as_str().to_owned(),
69	                    source_name: spec.local.name().as_str().to_owned(),
70	                    source_specifier: src.clone(),
71	                    is_type_only: node.export_kind.is_type() || spec.export_kind.is_type(),
72	                });
73	            }
74	        } else {
75	            // Local exports: `export interface Foo / export type Bar / export const X`
76	            if let Some(decl) = &node.declaration {
77	                let decl_name = declaration_name(decl);
78	                if let Some(name) = decl_name {
79	                    self.data.exports.push(LexedExport::LocalDeclaration {
80	                        name: name.to_owned(),
81	                        is_type_only: node.export_kind.is_type(),
82	                    });
83	                }
84	            }
85	            // Also handle `export { Foo }` without a source (local)
86	            for spec in &node.specifiers {
87	                self.data.exports.push(LexedExport::LocalDeclaration {
88	                    name: spec.exported.name().as_str().to_owned(),
89	                    is_type_only: node.export_kind.is_type() || spec.export_kind.is_type(),
90	                });
91	            }
92	        }
93	
94	        // Walk the declaration so sub-visitors (interface, type alias, etc.) fire
95	        walk::walk_export_named_declaration(self, node);
96	    }
97	
98	    fn visit_export_all_declaration(&mut self, node: &ExportAllDeclaration<'a>) {
99	        let src = node.source.value.as_str().to_owned();
100	        if let Some(ns) = &node.exported {
101	            // `export * as Ns from "./y"`
102	            self.data.exports.push(LexedExport::ReExportNamespace {
103	                namespace: ns.name().as_str().to_owned(),
104	                source_specifier: src,
105	            });
106	        } else {
107	            // `export * from "./y"`
108	            self.data
109	                .exports
110	                .push(LexedExport::ReExportAll { source_specifier: src, is_type_only: node.export_kind.is_type() });
111	        }
112	    }
113	
114	    fn visit_ts_interface_declaration(&mut self, node: &TSInterfaceDeclaration<'a>) {
115	        let name = node.id.name.as_str();
116	        let key = self.scoped_key(name);
117	
118	        let extends: Vec<ExtendsRef> = node.extends.iter().map(|ext| self.collect_extends(ext)).collect();
119	
120	        // Claim the interface's own leading comment before descending into props —
121	        // otherwise a short interface's first prop (processed next) can steal it via
122	        // find_jsdoc's proximity match, leaving the interface's own description empty.
123	        let (description, tags) = self.find_jsdoc_with_tags(node.span.start);
124	
125	        let props: Vec<RawProp> =
126	            node.body.body.iter().filter_map(|sig| self.collect_property_signature(sig)).collect();
127	
128	        self.data.interfaces.insert(
129	            key.clone(),
130	            CollectedInterface {
131	                scoped_key: key.clone(),
132	                name: name.into(),
133	                file_path: self.file_path.clone(),
134	                props,
135	                extends,
136	                description,
137	                tags,
138	            },
139	        );
140	
141	        // Record declared type parameter names (`interface Foo<TData, TValue>` →
142	        // ["TData", "TValue"]) so the resolver can recognize bare references to
143	        // them inside the interface's own body as expected generic placeholders
144	        // rather than unresolvable types — see `resolver/chain.rs`.
145	        if let Some(type_parameters) = &node.type_parameters {
146	            let params: Vec<TypeName> = type_parameters.params.iter().map(|p| p.name.name.as_str().into()).collect();
147	            if !params.is_empty() {
148	                self.data.interface_type_params.insert(key, params);
149	            }
150	        }
151	
152	        // Don't walk children — we've extracted everything we need
153	    }
154	
155	    fn visit_ts_type_alias_declaration(&mut self, node: &TSTypeAliasDeclaration<'a>) {
156	        let name = node.id.name.as_str();
157	        let key = self.scoped_key(name);
158	
159	        let Some(alias) = self.classify_type_alias(name, &node.type_annotation) else {
160	            return;
161	        };
162	        self.data.type_aliases.insert(key.clone(), alias);
163	
164	        // Record declared type parameter names (`type Assign<T, U> = ...` → ["T", "U"])
165	        // so the resolver can substitute call-site arguments into the alias body —
166	        // see `resolver/substitute.rs`. Absent entry = non-generic alias.
167	        if let Some(type_parameters) = &node.type_parameters {
168	            let params: Vec<TypeName> = type_parameters.params.iter().map(|p| p.name.name.as_str().into()).collect();
169	            if !params.is_empty() {
170	                self.data.type_alias_params.insert(key, params);
171	            }
172	        }
173	    }
174	
175	    fn visit_ts_module_declaration(&mut self, node: &TSModuleDeclaration<'a>) {
176	        // `declare module "foo"` (string-literal id) isn't a dotted-name namespace
177	        // like `namespace Foo { ... }` — its members aren't referenced as `foo.Bar`,
178	        // so only push an identifier-named namespace onto the qualifying stack.
179	        let pushed = match &node.id {
180	            TSModuleDeclarationName::Identifier(id) => {
181	                self.namespace_stack.push(id.name.as_str().into());
182	                true
183	            }
184	            TSModuleDeclarationName::StringLiteral(_) => false,
185	        };
186	
187	        walk::walk_ts_module_declaration(self, node);
188	
189	        if pushed {
190	            self.namespace_stack.pop();
191	        }
192	    }
193	
194	    fn visit_ts_enum_declaration(&mut self, node: &TSEnumDeclaration<'a>) {
195	        let enum_name = node.id.name.as_str();
196	        let key = self.scoped_key(enum_name);
197	
198	        let entries: Vec<EnumEntry> = node
199	            .body
200	            .members
201	            .iter()
202	            .filter_map(|member| {
203	                let name = match &member.id {
204	                    TSEnumMemberName::Identifier(id) => id.name.as_str().to_owned(),
205	                    TSEnumMemberName::String(s) => s.value.as_str().to_owned(),
206	                    TSEnumMemberName::ComputedString(s) => s.value.as_str().to_owned(),
207	                    TSEnumMemberName::ComputedTemplateString(_) => return None,
208	                };
209	
210	                let value = match &member.initializer {
211	                    Some(init) => {
212	                        self.expression_to_enum_value(init).unwrap_or_else(|| EnumValue::String(name.clone()))
213	                    }
214	                    None => EnumValue::String(name.clone()),
215	                };
216	
217	                let description = self.find_jsdoc(member.span.start);
218	                Some(EnumEntry { name, value, description })
219	            })
220	            .collect();
221	
222	        if !entries.is_empty() {
223	            self.data.enums.insert(key, entries);
224	        }
225	    }
226	
227	    fn visit_variable_declaration(&mut self, node: &VariableDeclaration<'a>) {
228	        for declarator in &node.declarations {
229	            self.try_collect_const_enum(declarator);
230	            self.try_collect_const_array(declarator);
231	            // Collect cva() / tv() variant definitions for all file types (.ts and .tsx)
232	            if let BindingPattern::BindingIdentifier(id) = &declarator.id {
233	                let name = id.name.as_str().to_owned();
234	                self.try_collect_cva_call(declarator, &name);
235	            }
236	            if self.is_tsx {
237	                if let Some(name) = self.extract_pascal_name(declarator) {
238	                    if let Some(mapping) = self
239	                        .try_fc_annotation(declarator, &name)
240	                        .or_else(|| self.try_forward_ref(declarator, &name))
241	                        .or_else(|| self.try_hoc_wrapped(declarator, &name))
242	                    {
243	                        self.data.component_mappings.push(mapping);
244	                        continue;
245	                    }
246	                    // try_rename_identifier_wrapped_component is itself a give-up-quietly
247	                    // path (a bare/wrapped identifier re-binding, not a props-bearing
248	                    // component candidate) — only record a skip when even that finds
249	                    // nothing, so plain aliasing (`const Button = InternalButton;`)
250	                    // doesn't spuriously report as an unsupported candidate. Also skip
251	                    // no-initializer declarations (`declare var Date: DateConstructor`) —
252	                    // those are ambient type-only bindings handled by Pattern 5 below
253	                    // (or legitimately not components at all), not failed candidates.
254	                    if declarator.init.is_some() && !self.try_rename_identifier_wrapped_component(declarator, &name) {
255	                        self.record_skip(
256	                            DiagnosticCode::SkippedCandidate,
257	                            format!(
258	                                "'{name}' is a PascalCase binding but matched no known component pattern \
259	                                 (FC annotation, forwardRef, HOC wrapper, or identifier alias)"
260	                            ),
261	                            declarator.span,
262	                        );
263	                    }
264	                }
265	            }
266	            // Pattern 5: declare const Button: React.ForwardRefExoticComponent<ButtonProps & RefAttributes<E>>
267	            // Common in .d.ts files — no initializer, just a type annotation
268	            if declarator.init.is_none() {
269	                if let Some(name) = self.extract_pascal_name(declarator) {
270	                    if let Some(mapping) = self.try_forward_ref_exotic_decl(declarator, &name) {
271	                        self.data.component_mappings.push(mapping);
272	                    }
273	                }
274	            }
275	        }
276	        walk::walk_variable_declaration(self, node);
277	    }
278	
279	    fn visit_function(&mut self, func: &Function<'a>, flags: ScopeFlags) {
280	        // Pattern 4: `function Button(props: ButtonProps) { ... }`
281	        if self.is_tsx {
282	            if let Some(id) = &func.id {
283	                let name = id.name.as_str();
284	                if is_pascal_case(name) && func.r#type == FunctionType::FunctionDeclaration {
285	                    if let Some(first_param) = func.params.items.first() {
286	                        if let Some(type_ann) = &first_param.type_annotation {
287	                            if let Some((props_name, type_args)) =
288	                                self.extract_type_name_from_type(&type_ann.type_annotation)
289	                            {
290	                                let (description, tags) = self.find_jsdoc_with_tags(func.span.start);
291	                                let param_defaults = self.extract_param_defaults(&func.params);
292	                                self.data.component_mappings.push(ComponentMapping {
293	                                    component_name: name.to_owned(),
294	                                    props_type_name: props_name,
295	                                    props_type_args: type_args,
296	                                    file_path: self.file_path.clone(),
297	                                    description,
298	                                    tags,
299	                                    span_start: func.span.start,
300	                                    span_end: func.span.end,
301	                                    param_defaults,
302	                                });
303	                            } else {
304	                                self.record_skip(
305	                                    DiagnosticCode::SkippedCandidate,
306	                                    format!(
307	                                        "'{name}' is a PascalCase function declaration whose first param's type \
308	                                         annotation isn't a recognizable props type reference"
309	                                    ),
310	                                    type_ann.span,
311	                                );
312	                            }
313	                        } else {
314	                            self.record_skip(
315	                                DiagnosticCode::SkippedCandidate,
316	                                format!("'{name}' is a PascalCase function declaration with an untyped first param"),
317	                                first_param.span,
318	                            );
319	                        }
320	                    }
321	                }
322	            }
323	        }
324	        walk::walk_function(self, func, flags);
325	    }
326	
327	    fn visit_expression_statement(&mut self, node: &ExpressionStatement<'a>) {
328	        self.try_scan_display_name(node);
329	        self.try_scan_default_props(node);
330	        walk::walk_expression_statement(self, node);
331	    }
332	}
