215	impl<'src> SourceDataCollector<'src> {
216	    fn new(path: &Utf8Path, source: &'src str, is_tsx: bool) -> Self {
217	        Self {
218	            file_path: path.to_owned(),
219	            source,
220	            is_tsx,
221	            data: SourceData::default(),
222	            comments: Vec::new(),
223	            imported_names: FxHashSet::default(),
224	            consumed_jsdoc: FxHashSet::default(),
225	            namespace_stack: Vec::new(),
226	            pending_display_name_renames: Vec::new(),
227	            aliased_away: FxHashSet::default(),
228	        }
229	    }
230	
231	    /// Record that a recognized-but-malformed AST shape was skipped — distinct
232	    /// from "wrong shape, not a candidate at all" (which stays silent). Used by
233	    /// `classify_type_alias`'s Omit/Pick/Partial/Required/Readonly arms and the
234	    /// component-detector chains in `visit.rs` when a shape matches a known
235	    /// pattern but is missing/malformed pieces the pattern requires.
236	    pub(super) fn record_skip(&mut self, code: DiagnosticCode, message: impl Into<String>, span: Span) {
237	        let _ = span; // no line/column conversion helper exists yet; kept for future use and call-site documentation
238	        self.data.diagnostics.push(Diagnostic {
239	            severity: DiagnosticSeverity::Info,
240	            message: message.into(),
241	            file: Some(self.file_path.to_string()),
242	            line: None,
243	            column: None,
244	            help: None,
245	            code,
246	        });
247	    }
248	
249	    pub(super) fn scoped_key(&self, name: &str) -> String {
250	        if self.namespace_stack.is_empty() {
251	            format!("{}:{}", self.file_path, name)
252	        } else {
253	            format!("{}:{}.{}", self.file_path, self.namespace_stack.join("."), name)
254	        }
255	    }
256	
257	    fn finish(mut self) -> SourceData {
258	        // Filtered by original identifier first, before any displayName rename
259	        // below can change what identifier a mapping currently answers to.
260	        if !self.aliased_away.is_empty() {
261	            let aliased_away = &self.aliased_away;
262	            self.data.component_mappings.retain(|m| !aliased_away.contains(m.component_name.as_str()));
263	        }
264	        for (obj_name, display_name) in self.pending_display_name_renames.drain(..) {
265	            if let Some(mapping) = self.data.component_mappings.iter_mut().find(|m| m.component_name == obj_name) {
266	                mapping.component_name = display_name;
267	            }
268	        }
269	        self.data
270	    }
