733	
734	    pub(super) fn collect_property_signature<'a>(&mut self, sig: &TSSignature<'a>) -> Option<RawProp> {
735	        match sig {
736	            TSSignature::TSPropertySignature(ps) => {
737	                let name = ps.key.static_name()?.to_string();
738	                let collected_type = ps
739	                    .type_annotation
740	                    .as_ref()
741	                    .map(|ta| self.ts_type_to_collected(&ta.type_annotation))
742	                    .unwrap_or(CollectedType::Any);
743	
744	                let (description, tags) = self.find_jsdoc_with_tags(ps.span.start);
745	
746	                Some(RawProp {
747	                    name,
748	                    collected_type,
749	                    required: !ps.optional,
750	                    description,
751	                    tags,
752	                    span_start: ps.span.start,
753	                    span_end: ps.span.end,
754	                })
755	            }
756	            TSSignature::TSMethodSignature(ms) => {
757	                let name = ms.key.static_name()?.to_string();
758	                let (description, tags) = self.find_jsdoc_with_tags(ms.span.start);
759	                let params: Vec<CollectedType> = ms
760	                    .params
761	                    .items
762	                    .iter()
763	                    .map(|p| {
764	                        p.type_annotation
765	                            .as_ref()
766	                            .map(|ta| self.ts_type_to_collected(&ta.type_annotation))
767	                            .unwrap_or(CollectedType::Any)
768	                    })
769	                    .collect();
770	                let param_names: Vec<Option<CompactString>> =
771	                    ms.params.items.iter().map(|p| binding_pattern_name(&p.pattern)).collect();
772	                let return_type = ms
773	                    .return_type
774	                    .as_ref()
775	                    .map(|rt| self.ts_type_to_collected(&rt.type_annotation))
776	                    .unwrap_or(CollectedType::Void);
777	                Some(RawProp {
778	                    name,
779	                    collected_type: CollectedType::Function { params, param_names, return_type: Box::new(return_type) },
780	                    required: !ms.optional,
781	                    description,
782	                    tags,
783	                    span_start: ms.span.start,
784	                    span_end: ms.span.end,
785	                })
786	            }
787	            _ => None,
788	        }
789	    }
790	}
