799	/// A parameter's simple identifier name, if it has one (not a destructured pattern).
800	fn binding_pattern_name(pattern: &BindingPattern) -> Option<CompactString> {
801	    match pattern {
802	        BindingPattern::BindingIdentifier(id) => Some(id.name.as_str().into()),
803	        _ => None,
804	    }
805	}
