1	//! Interface-adjacent collection: const enums, cva variants, displayName scanning.
2	
3	use oxc_ast::ast::*;
4	use rustc_hash::FxHashMap;
5	
6	use crate::types::{DefaultSource, EnumEntry, EnumValue, RawDefault};
7	
8	use super::SourceDataCollector;
9	
10	/// Extract the binding name and the `as const`-peeled inner expression from
11	/// `const NAME = <expr> as const` (or `<const><expr>`). Shared by
12	/// `try_collect_const_enum` (object) and `try_collect_const_array` (array) —
13	/// the only difference between them is what kind of expression they expect
14	/// once the cast is peeled off.
15	fn as_const_literal<'a, 'b>(decl: &'b VariableDeclarator<'a>) -> Option<(std::string::String, &'b Expression<'a>)> {
16	    let BindingPattern::BindingIdentifier(id) = &decl.id else { return None };
17	    let init = decl.init.as_ref()?;
18	    let inner = match init {
19	        Expression::TSAsExpression(tsa) => &tsa.expression,
20	        Expression::TSTypeAssertion(ta) => &ta.expression,
21	        _ => return None,
22	    };
23	    Some((id.name.as_str().to_owned(), inner))
24	}
25	
26	impl<'src> SourceDataCollector<'src> {
27	    // ─── `const` enum (as-const objects) collection ──────────────────────────
28	
29	    pub(super) fn try_collect_const_enum<'a>(&mut self, decl: &VariableDeclarator<'a>) {
30	        let Some((name, obj_expr)) = as_const_literal(decl) else { return };
31	
32	        let obj = match obj_expr {
33	            Expression::ObjectExpression(o) => o,
34	            _ => return,
35	        };
36	
37	        let entries: Vec<EnumEntry> = obj
38	            .properties
39	            .iter()
40	            .filter_map(|prop| match prop {
41	                ObjectPropertyKind::ObjectProperty(op) => {
42	                    let key = op.key.static_name()?.to_string();
43	                    let value = self.expression_to_enum_value(&op.value)?;
44	                    let desc = self.find_jsdoc(op.span.start);
45	                    Some(EnumEntry { name: key, value, description: desc })
46	                }
47	                _ => None,
48	            })
49	            .collect();
50	
51	        if !entries.is_empty() {
52	            let key = self.scoped_key(&name);
53	            self.data.enums.insert(key, entries);
54	        }
55	    }
56	
57	    // ─── `const` array (as-const arrays) collection ───────────────────────────
58	
59	    /// Detect: `const X = [...] as const` — a flat array literal, referenced via
60	    /// `(typeof X)[number]` to build a literal union without an explicit `enum`
61	    /// (e.g. antd's `type ButtonType = (typeof _ButtonTypes)[number]`). Distinct
62	    /// from `try_collect_const_enum` above (object, not array) and stored
63	    /// separately in `SourceData::const_arrays` — see that field's doc comment
64	    /// for why it isn't folded into `enums`.
65	    pub(super) fn try_collect_const_array<'a>(&mut self, decl: &VariableDeclarator<'a>) {
66	        let Some((name, arr_expr)) = as_const_literal(decl) else { return };
67	
68	        let arr = match arr_expr {
69	            Expression::ArrayExpression(a) => a,
70	            _ => return,
71	        };
72	
73	        let values: Vec<EnumValue> = arr
74	            .elements
75	            .iter()
76	            .filter_map(|el| el.as_expression())
77	            .filter_map(|e| self.expression_to_enum_value(e))
78	            .collect();
79	
80	        if !values.is_empty() {
81	            let key = self.scoped_key(&name);
82	            self.data.const_arrays.insert(key, values);
83	        }
84	    }
85	
86	    /// Detect: `const X = cva(base, { variants: { key: { val: "...", ... } } })`
87	    /// Store each variant key's values in self.data.enums under the scoped key.
88	    pub(super) fn try_collect_cva_call<'a>(&mut self, decl: &VariableDeclarator<'a>, name: &str) {
89	        let Some(init) = decl.init.as_ref() else { return };
90	        let call = match init {
91	            Expression::CallExpression(ce) => ce,
92	            _ => return,
93	        };
94	
95	        let callee_name = match &call.callee {
96	            Expression::Identifier(id) => id.name.as_str(),
97	            Expression::StaticMemberExpression(m) => m.property.name.as_str(),
98	            _ => return,
99	        };
100	
101	        if !matches!(callee_name, "cva" | "tv" | "defineRecipe" | "recipe" | "defineSlotRecipe") {
102	            return;
103	        }
104	
105	        // cva(baseClasses, { variants }) takes config at index 1; all other callees take it at index 0
106	        let arg_index = usize::from(callee_name == "cva");
107	        let Some(second_arg) = call.arguments.get(arg_index) else { return };
108	        let second_expr = match second_arg {
109	            Argument::SpreadElement(_) => return,
110	            other => match other.as_expression() {
111	                Some(e) => e,
112	                None => return,
113	            },
114	        };
115	        let obj = match second_expr {
116	            Expression::ObjectExpression(o) => o,
117	            _ => return,
118	        };
119	
120	        let variants_value = obj.properties.iter().find_map(|prop| {
121	            if let ObjectPropertyKind::ObjectProperty(p) = prop {
122	                if let PropertyKey::StaticIdentifier(key) = &p.key {
123	                    if key.name.as_str() == "variants" {
124	                        return match &p.value {
125	                            Expression::ObjectExpression(o) => Some(o),
126	                            _ => None,
127	                        };
128	                    }
129	                }
130	            }
131	            None
132	        });
133	        let Some(variants_value) = variants_value else { return };
134	
135	        let scoped_key = self.scoped_key(name);
136	        let mut entries: Vec<EnumEntry> = Vec::new();
137	
138	        for prop in &variants_value.properties {
139	            if let ObjectPropertyKind::ObjectProperty(variant_prop) = prop {
140	                let variant_key = match &variant_prop.key {
141	                    PropertyKey::StaticIdentifier(id) => id.name.as_str().to_owned(),
142	                    PropertyKey::StringLiteral(s) => s.value.as_str().to_owned(),
143	                    _ => continue,
144	                };
145	
146	                // The value is another object: { default: "...", sm: "...", ... }
147	                let values_obj = match &variant_prop.value {
148	                    Expression::ObjectExpression(o) => o,
149	                    _ => continue,
150	                };
151	
152	                for value_prop in &values_obj.properties {
153	                    if let ObjectPropertyKind::ObjectProperty(vp) = value_prop {
154	                        let value_name = match &vp.key {
155	                            PropertyKey::StaticIdentifier(id) => id.name.as_str().to_owned(),
156	                            PropertyKey::StringLiteral(s) => s.value.as_str().to_owned(),
157	                            _ => continue,
158	                        };
159	
160	                        entries.push(EnumEntry {
161	                            name: variant_key.clone(),
162	                            value: EnumValue::String(value_name),
163	                            description: String::new(),
164	                        });
165	                    }
166	                }
167	            }
168	        }
169	
170	        if !entries.is_empty() {
171	            self.data.enums.insert(scoped_key, entries);
172	        }
173	    }
174	
175	    pub(super) fn expression_to_enum_value<'a>(&self, expr: &Expression<'a>) -> Option<EnumValue> {
176	        match expr {
177	            Expression::StringLiteral(s) => Some(EnumValue::String(s.value.as_str().to_owned())),
178	            Expression::NumericLiteral(n) => Some(EnumValue::Number(n.value)),
179	            Expression::BooleanLiteral(b) => Some(EnumValue::Bool(b.value)),
180	            Expression::UnaryExpression(u) if u.operator == UnaryOperator::UnaryNegation => match &u.argument {
181	                Expression::NumericLiteral(n) => Some(EnumValue::Number(-n.value)),
182	                _ => None,
183	            },
184	            _ => None,
185	        }
186	    }
187	
188	    // ─── Static member assignment scanning ────────────────────────────────────
189	
190	    /// Parse `X.Y = <right>` out of an `ExpressionStatement`. Shared by every
191	    /// scan below that looks for a specific static property name being
192	    /// assigned on an already-detected component's binding.
193	    fn static_member_assignment<'a, 'b>(
194	        &self,
195	        stmt: &'b ExpressionStatement<'a>,
196	    ) -> Option<(std::string::String, &'b str, &'b Expression<'a>)> {
197	        let Expression::AssignmentExpression(assign) = &stmt.expression else { return None };
198	        let AssignmentTarget::StaticMemberExpression(sme) = &assign.left else { return None };
199	        let obj = self.expression_to_ident_name(&sme.object);
200	        Some((obj, sme.property.name.as_str(), &assign.right))
201	    }
202	
203	    // ─── `displayName` scanning ───────────────────────────────────────────────
204	
205	    /// Scan `Button.displayName = "Button"` and record the rename to apply
206	    /// once the whole file has been scanned (see `pending_display_name_renames`'s
207	    /// doc comment on why this can't be applied immediately).
208	    pub(super) fn try_scan_display_name<'a>(&mut self, stmt: &ExpressionStatement<'a>) {
209	        let Some((obj_name, "displayName", right)) = self.static_member_assignment(stmt) else { return };
210	        let Expression::StringLiteral(s) = right else { return };
211	        self.pending_display_name_renames.push((obj_name, s.value.as_str().to_owned()));
212	    }
213	
214	    // ─── `defaultProps` scanning ───────────────────────────────────────────────
215	
216	    /// Scan `Button.defaultProps = { size: 'md' }` and merge into the matching
217	    /// component mapping's `param_defaults` — the same field destructured
218	    /// defaults (`function Button({ size = 'md' })`) populate, via
219	    /// `extract_param_defaults`. Deprecated in React 19 but still shipped in
220	    /// real .d.ts/.tsx (MUI, among others).
221	    pub(super) fn try_scan_default_props<'a>(&mut self, stmt: &ExpressionStatement<'a>) {
222	        let Some((obj_name, "defaultProps", right)) = self.static_member_assignment(stmt) else { return };
223	        let Expression::ObjectExpression(defaults_obj) = right else { return };
224	
225	        let defaults: FxHashMap<std::string::String, RawDefault> = defaults_obj
226	            .properties
227	            .iter()
228	            .filter_map(|prop| match prop {
229	                ObjectPropertyKind::ObjectProperty(op) => {
230	                    let key = op.key.static_name()?.to_string();
231	                    let raw_default = self.eval_expr_as_default(&op.value, DefaultSource::DefaultProps);
232	                    Some((key, raw_default))
233	                }
234	                _ => None,
235	            })
236	            .collect();
237	
238	        if defaults.is_empty() {
239	            return;
240	        }
241	
242	        if let Some(mapping) = self.data.component_mappings.iter_mut().find(|m| m.component_name == obj_name) {
243	            mapping.param_defaults.extend(defaults);
244	        }
245	    }
246	}
