2	
3	use oxc_ast::ast::*;
4	
5	use crate::types::{DefaultSource, RawDefault};
6	
7	use super::SourceDataCollector;
8	
9	impl<'src> SourceDataCollector<'src> {
10	    /// Extract default values from destructured function parameters.
11	    ///
12	    /// Handles `({ size = 'md', disabled = false }: Props) => ...` patterns.
13	    pub(super) fn extract_param_defaults<'a>(
14	        &self,
15	        params: &FormalParameters<'a>,
16	    ) -> rustc_hash::FxHashMap<String, RawDefault> {
17	        let mut defaults = rustc_hash::FxHashMap::default();
18	
19	        let Some(first_param) = params.items.first() else {
20	            return defaults;
21	        };
22	        // In OXC 0.135, BindingPattern is an enum directly (not a struct with .kind)
23	        let BindingPattern::ObjectPattern(obj) = &first_param.pattern else {
24	            return defaults;
25	        };
26	
27	        for prop in &obj.properties {
28	            // In OXC 0.135, BindingProperty.value is BindingPattern.
29	            // A default value `{ size = 'md' }` is represented as
30	            // BindingProperty { key: "size", value: BindingPattern::AssignmentPattern { left: "size", right: 'md' } }
