65	pub(super) fn parse_jsdoc_text(raw: &str) -> String {
66	    let inner = raw.trim_start_matches("/**").trim_end_matches("*/");
67	
68	    let desc_lines: Vec<&str> = inner
69	        .lines()
70	        .map(|l| {
71	            let l = l.trim();
72	            let l = l.strip_prefix("* ").or_else(|| l.strip_prefix('*')).unwrap_or(l);
73	            l
74	        })
75	        .take_while(|l| !l.starts_with('@'))
76	        .collect();
77	
78	    desc_lines.join("\n").trim().to_owned()
79	}
