81	pub(super) fn extract_jsdoc_tags(raw: &str) -> BTreeMap<String, String> {
82	    let inner = raw.trim_start_matches("/**").trim_end_matches("*/");
83	    let mut tags: BTreeMap<String, String> = BTreeMap::new();
84	    let mut in_tags = false;
85	
86	    for line in inner.lines() {
87	        let line = line.trim();
88	        let line = line.strip_prefix("* ").or_else(|| line.strip_prefix('*')).unwrap_or(line);
89	        let line = line.trim();
90	
91	        if let Some(rest) = line.strip_prefix('@') {
92	            in_tags = true;
93	            let (tag, value) = if let Some(sp) = rest.find(char::is_whitespace) {
94	                let tag = &rest[..sp];
95	                let value = rest[sp..].trim();
96	                (tag, value)
97	            } else {
98	                (rest, "")
99	            };
100	
101	            // Special handling for @param — store as `param:propName`
102	            if tag == "param" {
103	                // Accepts both `@param propName description` and
104	                // `@param {type} propName description`.
105	                let value = value.trim_start_matches('{');
106	                let value =
107	                    if value.contains('}') { value.split_once('}').map(|x| x.1).unwrap_or("").trim() } else { value };
108	                if let Some(space) = value.find(char::is_whitespace) {
109	                    let prop_name = &value[..space];
110	                    let desc = value[space..].trim();
111	                    tags.insert(format!("param:{}", prop_name), desc.to_owned());
112	                } else if !value.is_empty() {
113	                    tags.insert(format!("param:{}", value), String::new());
114	                }
115	            } else {
116	                tags.insert(tag.to_owned(), value.to_owned());
117	            }
118	        } else if in_tags && !line.is_empty() {
119	            // Continuation of a tag — ignore for now
120	        }
121	    }
122	
123	    tags
124	}
