1	//! Import resolution map — built from `GlobalSourceData`, used read-only during resolution.
2	//!
3	//! Answers the question: "in file F, the name N was imported — what specifier and
4	//! canonical name does it refer to?"  Actual path resolution (specifier → absolute
5	//! path) is left to the caller via `oxc_resolver`.
6	
7	use camino::{Utf8Path, Utf8PathBuf};
8	use compact_str::CompactString;
9	use rustc_hash::FxHashMap;
10	
11	use crate::types::{GlobalSourceData, LexedExport};
12	
13	// ─── Public Types ─────────────────────────────────────────────────────────────
14	
15	/// Where an imported name comes from, as written in the source.
16	#[derive(Debug, Clone)]
17	pub struct ImportRef {
18	    /// The import specifier as written: `"@radix-ui/react-button"`, `"./types"`, etc.
19	    pub specifier: String,
20	    /// The exported name in the source module (original name before `as` rename).
21	    pub exported_name: CompactString,
22	    /// `true` for `import type { ... }` bindings.
23	    #[allow(dead_code)]
24	    pub is_type_only: bool,
25	}
26	
27	/// Result of walking one step of a re-export chain.
28	#[derive(Debug, Clone)]
29	pub enum ReExportStep {
30	    /// Found a named re-export — caller resolves `source_specifier` to a file and recurses.
31	    Named { source_specifier: String, source_name: String },
32	    /// Found one or more `export * from "..."` entries — caller checks each.
33	    Wildcards(Vec<String>),
34	}
35	
36	// ─── ImportResolutionMap ──────────────────────────────────────────────────────
37	
38	/// Maps `(consuming_file, local_name)` → import reference.
39	/// Built once from `GlobalSourceData`, then used read-only during parallel resolution.
40	pub struct ImportResolutionMap {
41	    /// `file_path` → (`local_name` → specifier + original exported name).
42	    /// Nested (rather than a flat `(Utf8PathBuf, CompactString)` key) so lookups can
43	    /// borrow `&Utf8Path` directly instead of cloning the whole path per call.
44	    /// Note: we store the specifier string, not the resolved file path.
45	    /// The resolver calls `oxc_resolver` to turn specifiers into absolute paths.
46	    bindings: FxHashMap<Utf8PathBuf, FxHashMap<CompactString, ImportRef>>,
47	}
48	
49	impl ImportResolutionMap {
50	    /// Build from a fully-merged `GlobalSourceData`.
51	    /// Called once per extraction run, before parallel resolution starts.
52	    ///
53	    /// No I/O — pure data transformation.
54	    pub fn build(global: &GlobalSourceData) -> Self {
55	        let mut bindings: FxHashMap<Utf8PathBuf, FxHashMap<CompactString, ImportRef>> = FxHashMap::default();
56	
57	        for (file_path, import_bindings) in &global.import_map {
58	            let per_file = bindings.entry(file_path.clone()).or_default();
59	            for binding in import_bindings {
60	                per_file.insert(
61	                    binding.local_name.clone(),
62	                    ImportRef {
63	                        specifier: binding.specifier.clone(),
64	                        exported_name: binding.exported_name.clone(),
65	                        is_type_only: binding.is_type_only,
66	                    },
67	                );
68	            }
69	        }
70	
71	        Self { bindings }
72	    }
73	
74	    /// Given a file and a local name used in that file, return where it was imported from.
75	    ///
76	    /// Returns `None` if the name is locally defined (not imported).
77	    pub fn find_import(&self, file: &Utf8Path, local_name: &str) -> Option<&ImportRef> {
78	        self.bindings.get(file)?.get(local_name)
79	    }
80	
81	    /// Walk one step of the re-export chain for `barrel_file`.
82	    ///
83	    /// - If a `ReExportNamed` entry matches `exported_name`, returns `Named { .. }`.
84	    /// - If no named match is found but there are `ReExportAll` entries, returns `Wildcards(..)`.
85	    /// - Returns `None` if the barrel file has no relevant re-exports.
86	    pub fn resolve_reexport_chain(
87	        &self,
88	        barrel_file: &Utf8Path,
89	        exported_name: &str,
90	        global: &GlobalSourceData,
91	    ) -> Option<ReExportStep> {
92	        let exports = global.re_export_map.get(barrel_file)?;
93	
94	        let mut wildcard_specifiers: Vec<String> = Vec::new();
95	
96	        for export in exports {
97	            match export {
98	                LexedExport::ReExportNamed { local_name, source_name, source_specifier, .. } => {
99	                    if local_name == exported_name {
100	                        return Some(ReExportStep::Named {
101	                            source_specifier: source_specifier.clone(),
102	                            source_name: source_name.clone(),
103	                        });
104	                    }
105	                }
106	                LexedExport::ReExportAll { source_specifier, .. } => {
107	                    wildcard_specifiers.push(source_specifier.clone());
108	                }
109	                // Namespace re-exports and local declarations are not relevant here.
110	                _ => {}
111	            }
112	        }
113	
114	        if !wildcard_specifiers.is_empty() {
115	            Some(ReExportStep::Wildcards(wildcard_specifiers))
116	        } else {
117	            None
118	        }
119	    }
120	}
