pub(crate) fn build(global: &GlobalSourceData) -> Self {
    let mut interfaces: FxHashMap<Utf8PathBuf, FxHashMap<CompactString, CollectedInterface>> = FxHashMap::default();
    let mut interface_type_params: FxHashMap<Utf8PathBuf, FxHashMap<CompactString, Vec<TypeName>>> =
        FxHashMap::default();
    for (key, iface) in &global.interfaces {
        let Some((file, name)) = key.rsplit_once(':') else { continue };
        let file = Utf8PathBuf::from(file);
        interfaces.entry(file.clone()).or_default().insert(CompactString::from(name), iface.clone());
        if let Some(params) = global.interface_type_params.get(key) {
            interface_type_params.entry(file).or_default().insert(CompactString::from(name), params.clone());
        }
    }

    let mut type_aliases: FxHashMap<Utf8PathBuf, FxHashMap<CompactString, CollectedTypeAlias>> =
        FxHashMap::default();
    let mut type_alias_params: FxHashMap<Utf8PathBuf, FxHashMap<CompactString, Vec<TypeName>>> =
        FxHashMap::default();
    for (key, alias) in &global.type_aliases {
        let Some((file, name)) = key.rsplit_once(':') else { continue };
        let file = Utf8PathBuf::from(file);
        type_aliases.entry(file.clone()).or_default().insert(CompactString::from(name), alias.clone());
        if let Some(params) = global.type_alias_params.get(key) {
            type_alias_params.entry(file).or_default().insert(CompactString::from(name), params.clone());
        }
    }

    Self { interfaces, type_aliases, type_alias_params, interface_type_params }
}

